actions.script:
import org.moqui.resource.ResourceReference

List results = []
List searchPaths = [
    "component://agi-ide/resources/screen/archetype",
    "component://agi-ai/mcp/resources/screen/archetype"
]

searchPaths.each { basePath ->
    try {
        ResourceReference dirRef = ec.resource.getLocationReference(basePath)
        if (dirRef != null && dirRef.getExists() && dirRef.isDirectory()) {
            dirRef.directoryEntries.each { entry ->
                if (entry.fileName.endsWith(".xml")) {
                    String rawName = entry.fileName.replace(".xml", "")
                    results.add([
                        name: rawName,
                        uri: entry.location,
                        description: "Canonical ${rawName} screen archetype layout"
                    ])
                }
            }
        }
    } catch (Exception ignore) {}
}

context.archetypes = results

import org.moqui.resource.ResourceReference

List results = []
String searchLoc = path ? (path.startsWith("component://") ? path : "component://${targetComponent}/${path}") : "component://${targetComponent}/screen"

try {
    ResourceReference dirRef = ec.resource.getLocationReference(searchLoc)
    if (dirRef != null && dirRef.getExists() && dirRef.isDirectory()) {
        dirRef.directoryEntries.each { entry ->
            boolean matchesExt = !extension || entry.fileName.endsWith(extension.startsWith(".") ? extension : ".${extension}")
            if (matchesExt) {
                results.add([
                    name: entry.fileName,
                    path: entry.location,
                    isDirectory: entry.isDirectory()
                ])
            }
        }
    }
} catch (Exception ex) {
    ec.logger.warn("⚠️ [workspace#ListFiles] Could not list entries at ${searchLoc}: ${ex.message}")
}

context.files = results
context.baseLocation = searchLoc
ec.logger.info("📁 [workspace#ListFiles] Discovered ${results.size()} entries at ${searchLoc}")
